import { StyleSheet, Text, View } from 'react-native';

import { fontFamily, radius, readableOn } from '@/theme/tokens';
import { useColors } from '@/theme/use-scheme';

type Props = {
  name: string;
  size?: number;
  /** Set only when the avatar stands alone; beside the name it is decorative. */
  standalone?: boolean;
};

/**
 * Initials avatar with a colour derived from the name (spec 08.5).
 *
 * The tint is picked from a fixed set rather than generated by hashing the name to a hue.
 * A free hue carries no contrast guarantee — at any given lightness much of the wheel is
 * too pale for white initials — so this draws from the five semantic colours, whose
 * contrast is already asserted by `scripts/check-contrast.py`, and lets `readableOn` pick
 * the initials colour per tint. Worst case across the five tints in both themes is
 * 4.52:1. Deterministic *and* legible, rather than deterministic and sometimes not.
 */
const TINTS = ['primary', 'accent', 'success', 'info', 'danger'] as const;

function tintFor(name: string) {
  // Sum of code points: stable across sessions and platforms, which a string hash with
  // implementation-defined behaviour would not be.
  let total = 0;
  for (let i = 0; i < name.length; i += 1) total += name.codePointAt(i) ?? 0;
  return TINTS[total % TINTS.length];
}

export function initialsOf(name: string) {
  const words = name.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return '?';
  const first = [...words[0]][0] ?? '';
  const last = words.length > 1 ? ([...words[words.length - 1]][0] ?? '') : '';
  return (first + last).toUpperCase();
}

export function Avatar({ name, size = 38, standalone = false }: Props) {
  const colors = useColors();

  const background = colors[tintFor(name)];
  // Per colour, not per theme: in light, white reads on `primary` (10.94:1) but not on
  // `accent` (3.05:1, where ink gives 6.02:1).
  const foreground = readableOn(background);

  return (
    <View
      style={[
        styles.base,
        { width: size, height: size, borderRadius: radius.pill, backgroundColor: background },
      ]}
      accessibilityRole={standalone ? 'image' : undefined}
      accessibilityLabel={standalone ? name : undefined}
      // See the note in `icon.tsx`: `aria-hidden` rather than the RN-only pair, which
      // this react-native-web version leaks to the DOM.
      aria-hidden={standalone ? undefined : true}
    >
      <Text
        style={[
          styles.initials,
          { fontSize: size * 0.36, lineHeight: size * 0.46, color: foreground },
        ]}
        // Initials must not shrink away when the OS font scale is large; the circle grows
        // with the layout instead.
        maxFontSizeMultiplier={1.4}
      >
        {initialsOf(name)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  base: { alignItems: 'center', justifyContent: 'center' },
  initials: { fontFamily: fontFamily.semibold, fontWeight: '600', letterSpacing: 0.5 },
});
